import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../shared/providers/providers.dart';
class ProviderScreen extends ConsumerStatefulWidget{const ProviderScreen({super.key});@override ConsumerState<ProviderScreen> createState()=>_State();}class _State extends ConsumerState<ProviderScreen>{int step=0;final title=TextEditingController(),phone=TextEditingController(),area=TextEditingController();String type='vehicle_with_driver';bool available=true;double lat=6.9271,lng=79.8612;Future<void> submit()async{try{await ref.read(apiProvider).dio.post('/provider/listings',data:{'listingType':type,'title':title.text,'phone':phone.text,'latitude':lat,'longitude':lng,'publicAreaName':area.text,'availableNow':available});if(mounted)showDialog(context:context,builder:(_)=>const AlertDialog(title:Text('Listing submitted'),content:Text('Your listing is now pending review.')));}catch(_){if(mounted)showDialog(context:context,builder:(_)=>const AlertDialog(title:Text('Could not submit'),content:Text('Sign in and complete your provider profile before creating a listing.')));}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create listing')),body:Stepper(currentStep:step,onStepContinue:(){if(step<4)setState(()=>step++);else submit();},onStepCancel:step==0?null:()=>setState(()=>step--),controlsBuilder:(c,d)=>Padding(padding:const EdgeInsets.only(top:18),child:Row(children:[FilledButton(onPressed:d.onStepContinue,child:Text(step==4?'Submit listing':'Continue')),const SizedBox(width:8),if(step>0)TextButton(onPressed:d.onStepCancel,child:const Text('Back'))])),steps:[Step(title:const Text('Listing type'),content:DropdownButtonFormField(value:type,items:const [DropdownMenuItem(value:'vehicle_with_driver',child:Text('Vehicle with driver')),DropdownMenuItem(value:'vehicle_without_driver',child:Text('Vehicle without driver')),DropdownMenuItem(value:'driver_only',child:Text('Driver only'))],onChanged:(x)=>setState(()=>type=x!))),Step(title:const Text('Vehicle or service information'),content:TextField(controller:title,decoration:const InputDecoration(labelText:'Listing title'))),Step(title:const Text('Availability'),content:SwitchListTile(value:available,onChanged:(x)=>setState(()=>available=x),title:const Text('Available now'))),Step(title:const Text('Service location'),content:Column(children:[TextField(controller:area,decoration:const InputDecoration(labelText:'Approximate area')),const SizedBox(height:8),Text('GPS: $lat, $lng (exact coordinates are never public)')])),Step(title:const Text('Contact and preview'),content:Column(children:[TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone number')),const SizedBox(height:12),Text(title.text.isEmpty?'Your listing preview will appear here.':title.text,style:Theme.of(context).textTheme.titleLarge)]))]));}
